@classmethod
def filter_search_query(cls, db_model: type[Model], query: QuerySet, session: BaseDBAsyncClient, search_type: SearchType, search: str, search_list: list[str]) -> QuerySet:
    """
        Filters a search query based on model attributes

        Can be overridden to support a more advanced search
        """
    if not cls._searchable_properties:
        raise AttributeError('Not Implemented')
    properties = cls._searchable_properties
    if search_type is SearchType.fuzzy:
        from mealie.services.query_filter.expressions import WordSimilarity
        annotations = {f'_search_similarity_{index}': WordSimilarity(prop, search) for index, prop in enumerate(properties)}
        query = query.annotate(**annotations)
        matches = Q()
        for key in annotations:
            condition: dict[str, Any] = {key + '__gte': cls._fuzzy_similarity_threshold}
            matches |= Q(**condition)
        return query.filter(matches).order_by('-_search_similarity_0')
    matches = Q()
    for prop in properties:
        for token in search_list:
            matches |= Q(**{prop + '__icontains': token})
    return query.filter(matches).annotate(_search_rank=Case(When(Q(**{properties[0] + '__icontains': search}), then=cast(Any, 1)), default=cast(Any, 0))).order_by('-_search_rank')

