@classmethod
def filter_search_query(cls, db_model, query: Select, session: Session, search_type: SearchType, search: str, search_list: list[str]) -> Select:
    """
        1. token search looks for any individual exact hit in name, description, and ingredients
        2. fuzzy search looks for trigram hits in name, description, and ingredients
        3. Sort order is determined by closeness to the recipe name
        Should search also look at tags?
        """
    if search_type is SearchType.fuzzy:
        ingredient_ids = session.execute(select(RecipeIngredientModel.id).filter(or_(RecipeIngredientModel.note_normalized.op('%>')(search), RecipeIngredientModel.original_text_normalized.op('%>')(search)))).scalars().all()
        session.execute(text(f'set pg_trgm.word_similarity_threshold = {cls._fuzzy_similarity_threshold};'))
        return query.filter(or_(RecipeModel.name_normalized.op('%>')(search), RecipeModel.description_normalized.op('%>')(search), RecipeModel.recipe_ingredient.any(RecipeIngredientModel.id.in_(ingredient_ids)))).order_by(func.least(RecipeModel.name_normalized.op('<->>')(search)))
    else:
        ingredient_ids = session.execute(select(RecipeIngredientModel.id).filter(or_(*[RecipeIngredientModel.note_normalized.like(f'%{ns}%') for ns in search_list], *[RecipeIngredientModel.original_text_normalized.like(f'%{ns}%') for ns in search_list]))).scalars().all()
        return query.filter(or_(*[RecipeModel.name_normalized.like(f'%{ns}%') for ns in search_list], *[RecipeModel.description_normalized.like(f'%{ns}%') for ns in search_list], RecipeModel.recipe_ingredient.any(RecipeIngredientModel.id.in_(ingredient_ids)))).order_by(desc(RecipeModel.name_normalized.like(f'%{search}%')))

