@classmethod
def filter_search_query(cls, db_model, query, session, search_type: SearchType, search: str, search_list: list[str]):
    from tortoise.expressions import Case, Q, Subquery, When
    from mealie.db.models.recipe.ingredient import RecipeIngredientModel
    fields = ['name_normalized', 'description_normalized']
    ingredient_fields = ['note_normalized', 'original_text_normalized']
    if search_type is SearchType.fuzzy:
        from mealie.services.query_filter.expressions import WordSimilarity
        query = query.annotate(_name_similarity=WordSimilarity('name_normalized', search), _description_similarity=WordSimilarity('description_normalized', search))
        ingredients = RecipeIngredientModel.annotate(**{f'_ingredient_similarity_{index}': WordSimilarity(field, search) for index, field in enumerate(ingredient_fields)}).filter(Q(_ingredient_similarity_0__gte=cls._fuzzy_similarity_threshold) | Q(_ingredient_similarity_1__gte=cls._fuzzy_similarity_threshold))
        return query.filter(Q(_name_similarity__gte=cls._fuzzy_similarity_threshold) | Q(_description_similarity__gte=cls._fuzzy_similarity_threshold) | Q(id__in=Subquery(ingredients.values('recipe_id')))).order_by('-_name_similarity')
    ingredient_matches = Q()
    recipe_matches = Q()
    for token in search_list:
        for field in fields:
            recipe_matches |= Q(**{field + '__icontains': token})
        for field in ingredient_fields:
            ingredient_matches |= Q(**{field + '__icontains': token})
    return query.filter(recipe_matches | Q(id__in=Subquery(RecipeIngredientModel.filter(ingredient_matches).values('recipe_id')))).annotate(_search_rank=Case(When(name_normalized__icontains=search, then=cast(Any, 1)), default=cast(Any, 0))).order_by('-_search_rank')

